'use strict';
const STORE=EXAM.store,DURATION=75*60*1000;
const needsReview=f=>f.type==='text'||f.type==='table'||f.type==='math';
const sectionIds=EXAM.sections.map((_,i)=>'ABC'[i]);
const isChoice=f=>f.type==='choice'||f.type==='select';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=QUESTIONS.flatMap(q=>q.fields.map(f=>({...f,section:q.section,qid:q.id,topic:f.topic||q.topic})));
let state=null,storageOK=true;
try{const raw=localStorage.getItem(STORE);if(raw){const s=JSON.parse(raw);if(s.version===1&&Number.isFinite(s.started)&&s.answers&&typeof s.answers==='object'&&['exam','result'].includes(s.status))state=s;}}catch{storageOK=false;}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{storageOK=false;}}
function norm(s){return String(s??'').toLowerCase().normalize('NFKC').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();}
function contains(s,t){return new RegExp('(?:^|\\s)'+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:$|\\s)').test(s);}
function answered(f){let a=state.answers[f.id];return f.type==='table'?Array.isArray(a)&&a.length===6&&a.every(v=>String(v).trim()):isChoice(f)?Number.isInteger(a):typeof a==='string'&&a.trim().length>0;}
function anyAnswer(f){let a=state.answers[f.id];return f.type==='table'?Array.isArray(a)&&a.some(v=>String(v).trim()):answered(f);}
function numericValue(raw,units=[]){
 let s=String(raw??'').normalize('NFKC').trim().toLowerCase().replace(/−/g,'-').replace(/\s+/g,' ');
 if(!s)return null;
 for(const unit of [...units].sort((a,b)=>b.length-a.length)){
  const u=unit.toLowerCase();
  if(s.startsWith(u)){s=s.slice(u.length).trim();break;}
  if(s.endsWith(u)){s=s.slice(0,-u.length).trim();break;}
 }
 // Parse numbers only; never evaluate expressions or JavaScript.
 const mixed=s.match(/^([+-]?\d+)\s+(\d+)\s*\/\s*(\d+)$/);
 if(mixed){const den=Number(mixed[3]);if(!den)return null;return Number(mixed[1])+(mixed[1].startsWith('-')?-1:1)*Number(mixed[2])/den;}
 const fraction=s.match(/^([+-]?\d+)\s*\/\s*(\d+)$/);
 if(fraction){const den=Number(fraction[2]);return den?Number(fraction[1])/den:null;}
 if(/^[+-]?\d{1,3}(?:,\d{3})+(?:\.\d+)?$/.test(s))s=s.replace(/,/g,'');
 else if(s.includes(','))return null;
 if(/^[+-]?\d{1,3}(?: \d{3})+(?:\.\d+)?$/.test(s))s=s.replace(/ /g,'');
 if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))return null;
 const value=Number(s);return Number.isFinite(value)?value:null;
}
function timeValue(raw){
 let s=String(raw??'').trim().toLowerCase().replace(/^(?:jam|pukul)\s*/,'');
 let m=s.match(/^(\d{1,2})[:.](\d{2})$/);if(!m&&/^\d{4}$/.test(s))m=[s,s.slice(0,2),s.slice(2)];
 if(!m)return null;const h=Number(m[1]),mins=Number(m[2]);return h<24&&mins<60?h*60+mins:null;
}
function mathMatches(f,answer){
 if(f.kind==='word')return (f.accepted||[f.answer]).some(v=>norm(v)===norm(answer));
 if(f.kind==='time'){const actual=timeValue(answer),expected=timeValue(f.answer);return actual!==null&&actual===expected;}
 const actual=numericValue(answer,f.units||[]);return actual!==null&&Math.abs(actual-f.answer)<1e-9;
}
function mathCoverage(){
 const topics=[...new Set(fields.map(f=>f.topic))];return tableHTML([['Unit Tahun 6','Markah'],...topics.map(t=>[t,fields.filter(f=>f.topic===t).reduce((n,f)=>n+f.max,0)])]);
}
function topicResults(){
 const topics=[...new Set(fields.map(f=>f.topic))];return '<h2>Prestasi mengikut topik</h2>'+tableHTML([['Topik','Markah'],...topics.map(t=>{const fs=fields.filter(f=>f.topic===t);return [t,fs.reduce((n,f)=>n+score(f),0)+' / '+fs.reduce((n,f)=>n+f.max,0)];})]);
}
function autoScore(f){const a=state.answers[f.id];if(isChoice(f))return a===f.answer?1:0;
 if(f.type==='math')return mathMatches(f,a)?f.max:0;
 if(EXAM.key==='matematik'&&f.type==='text'){const n=norm(a);if(f.reasonAlternatives)return n&&f.reasonAlternatives.some(groups=>groups.every(alternatives=>alternatives.some(term=>n.includes(term))))?Math.min(1,f.max):0;return n&&((/tiada|tidak ada|tidak mempunyai|tidak mengandungi/.test(n)&&n.includes('hijau'))||(n.includes('hanya')&&n.includes('merah')&&n.includes('biru')))?1:0;}
 if(f.type==='table'){if(!Array.isArray(a))return 0;const n=a.map(norm);const headers=n[0]?.includes('ketinggian')&&contains(n[0],'m')&&n[1]?.includes('tekanan')&&contains(n[1],'kpa');const pairs=[[n[2]?.replace(/ /g,''),n[3]],[n[4]?.replace(/ /g,''),n[5]]];const data=pairs.some(v=>v[0]==='0'&&v[1]==='100')&&pairs.some(v=>v[0]==='2000'&&v[1]==='80');return Number(!!headers)+Number(data);}
 const n=norm(a);if(!n)return 0;
 // Written scores are suggestions only: parent review remains required.
 if(EXAM.key==='sejarah'){if(f.concepts)return Math.min(f.max,f.concepts.filter(group=>group.some(term=>n.includes(term))).length);return Math.min(f.max,(f.rules||[]).reduce((sum,groups)=>sum+Number(groups.every(or=>or.some(t=>n.includes(t)))),0));}
 if(f.id==='c3c'){const concepts=[['larang','kuatkuasa'],['penetasan'],['perlindungan','wartakan'],['cahaya','lampu'],['kempen']];return Math.min(2,concepts.filter(v=>v.some(t=>n.includes(t))).length);}
 if(f.id==='c4a')return /^(jambatan\s+)?q$/.test(n)?1:0;
 if(f.id==='c4f'){return Number(/(?:^|\s)(?:menara\s+)?s(?:\s|$)/.test(n)&&!n.includes('menara r'))+Number(n.includes('tapak')&&/lebar|luas/.test(n));}
 return f.rules.reduce((sum,groups)=>sum+Number(groups.every(or=>or.some(t=>t.length===1?contains(n,t):n.includes(t)))),0);
}
function score(f){const m=state.overrides?.[f.id];return Number.isInteger(m)&&m>=0&&m<=f.max?m:autoScore(f);}
function total(section){return fields.filter(f=>!section||f.section===section).reduce((n,f)=>n+score(f),0);}
function grade(p){return p>=80?'A':p>=65?'B':p>=50?'C':p>=40?'D':'E';}
function tableHTML(rows){return '<div class="table-wrap"><table>'+rows.map((row,i)=>'<tr>'+row.map(cell=>`<${i?'td':'th'}>${esc(cell)}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';}
function toast(message){$('#toast')?.remove();const t=document.createElement('div');t.id='toast';t.role='status';t.textContent=message;document.body.appendChild(t);setTimeout(()=>t.remove(),3500);}
async function confirmAction(title,body,label='Teruskan'){const d=$('#confirm');$('#dialog-title').textContent=title;$('#dialog-body').textContent=body;$('#dialog-ok').textContent=label;d.returnValue='';d.showModal();return new Promise(r=>d.addEventListener('close',()=>r(d.returnValue==='confirm'),{once:true}));}
function welcome(){const resume=state?.status==='exam';$('#main').innerHTML=`${EXAM.key==='matematik'?`<nav class="set-picker no-print" aria-label="Pilih set Matematik"><a href="matematik.html" ${EXAM.setNumber==='01'?'aria-current="page"':''}>Matematik · Set 1</a><a href="matematik-set2.html" ${EXAM.setNumber==='02'?'aria-current="page"':''}>Matematik · Set 2</a></nav>`:''}<div class="hero"><section><div class="eyebrow">${esc(EXAM.eyebrow)}</div><h1>Fikir. Jawab.<br><span class="accent">${esc(EXAM.heading)}</span></h1><p class="muted">Latihan UASA ${esc(EXAM.label)} Tahun 6 berdasarkan topik ulang kaji kamu. Cuba satu kertas penuh, kemudian kenal pasti bahagian yang boleh diperbaiki.</p><div class="meta-grid"><div><strong>50</strong><span>markah penuh</span></div><div><strong>75</strong><span>minit menjawab</span></div><div><strong>${EXAM.sections.length}</strong><span>bahagian</span></div></div><p class="start-warning">${EXAM.key==='matematik'?'Jawab semua soalan tanpa kalkulator. Gunakan titik untuk perpuluhan, / untuk pecahan dan HH:MM bagi masa.':'Jawab semua soalan.'} Jawapan disimpan pada pelayar ini secara automatik.</p></section><section class="card start-card"><span class="pill">KERTAS LATIHAN ${EXAM.setNumber}</span><h2>Jom uji kefahaman.</h2><label for="student">Nama panggilan <small>(pilihan)</small></label><input id="student" type="text" maxlength="60" placeholder="Contoh: Addeena" autocomplete="off" value="${esc(state?.name||'')}"><button class="full" id="start">${resume?'Sambung peperiksaan':state?.status==='result'?'Lihat keputusan':'Mula peperiksaan'} →</button>${state?'<button id="fresh" class="ghost full">Mulakan percubaan baharu</button>':''}<div class="notice"><strong>Bagaimana markah dikira?</strong><br>${EXAM.key==='matematik'?'Jawapan akhir disemak secara automatik. Jawapan tepat mendapat markah penuh cadangan. Jika jawapan salah, ibu bapa boleh beri markah separa bagi jalan kerja yang betul mengikut skema. Alasan bertulis juga perlu disemak.':'A & B ditanda secara automatik. Jawapan bertulis C menerima cadangan markah berdasarkan kata kunci dan perlu disemak ibu bapa mengikut skema sebelum gred disahkan.'}</div><p class="privacy">Tiada akaun diperlukan. Nama dan jawapan tidak dihantar ke pangkalan data. Rekod pada peranti ini sahaja.${storageOK?'':' Penyimpanan pelayar tidak tersedia; jangan tutup atau muat semula halaman.'}</p></section></div><div class="section-cards">${EXAM.sections.map((section,i)=>`<div class="card"><span class="pill">BAHAGIAN ${'ABC'[i]}</span><h3>${section.title}</h3><p>${section.max} markah · ${section.desc}</p></div>`).join('')}</div>${EXAM.key==='matematik'?'<details class="card coverage"><summary>Agihan markah lapan unit Tahun 6</summary>'+mathCoverage()+'</details>':''}<p class="no-print"><a href="./" class="subject-back">← Pilih subjek lain</a></p>`;
 $('#start').onclick=()=>{if(state){state.name=$('#student').value.trim();persist();if(state.status==='result')renderResults();else{if(Date.now()-state.started>=DURATION)submit(true);else renderExam();}}else start();};$('#fresh')?.addEventListener('click',async()=>{if(await confirmAction('Mulakan semula?','Rekod percubaan pada peranti ini akan digantikan. Muat turun keputusan dahulu jika perlu.','Mulakan baharu'))start();});}
function start(){const name=$('#student')?.value.trim()||state?.name||'';state={version:1,status:'exam',name,started:Date.now(),answers:{},workings:{},flags:[],index:0,overrides:{},confirmed:false};persist();renderExam();}
function nav(){return sectionIds.map(section=>`<div class="nav-group"><span class="eyebrow">BAHAGIAN ${section}</span><div class="nav-grid ${section==='A'?'':'compact'}">${QUESTIONS.map((q,i)=>q.section===section?`<button class="nav-btn ${i===state.index?'active':''} ${q.fields.every(answered)?'answered':''} ${state.flags.includes(q.id)?'flagged':''}" data-nav="${i}" aria-label="Bahagian ${section}, soalan ${q.title}, ${q.fields.every(answered)?'lengkap':'belum lengkap'}" ${i===state.index?'aria-current="step"':''}>${section}${q.id.slice(1)}</button>`:'').join('')}</div></div>`).join('');}
function fieldHTML(f){const a=state.answers[f.id];let input='';if(isChoice(f)){input='<div class="options">'+f.options.map((o,i)=>`<label class="option"><input type="radio" name="${f.id}" value="${i}" ${a===i?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></label>`).join('')+'</div>';}else if(f.type==='table'){input='<div class="table-wrap"><table class="answer-table"><tbody>'+[0,1,2].map(r=>'<tr>'+[0,1].map(c=>{let j=r*2+c;return `<td><input type="text" data-table="${f.id}" data-cell="${j}" aria-label="${r===0?'Tajuk lajur '+(c+1):'Baris '+r+', lajur '+(c+1)}" placeholder="${r===0?'Tajuk & unit':'Nilai'}" maxlength="100" value="${esc(a?.[j]||'')}"></td>`;}).join('')+'</tr>').join('')+'</tbody></table></div>';}else input=`<textarea id="${f.id}" name="${f.id}" maxlength="2500" placeholder="Tulis jawapan kamu di sini...">${esc(a||'')}</textarea>`;
 if(f.type==='select')input=`<select name="${f.id}" data-choice="${f.id}" aria-labelledby="label-${f.id}"><option value="">Pilih jawapan...</option>${f.options.map((o,i)=>`<option value="${i}" ${a===i?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
 if(f.type==='math')input=`<label class="math-answer-label" for="${f.id}">Jawapan akhir ${f.displayUnit?'('+esc(f.displayUnit)+')':''}</label><input id="${f.id}" name="${f.id}" data-math="${f.id}" type="text" maxlength="160" autocomplete="off" value="${esc(a||'')}" placeholder="${f.kind==='time'?'HH:MM':f.kind==='word'?'Tulis jawapan':'Tulis nilai jawapan'}"><label class="working-label" for="work-${f.id}">Jalan kerja <small>(untuk semakan markah kaedah)</small></label><textarea id="work-${f.id}" data-work="${f.id}" maxlength="2500" placeholder="Tulis langkah pengiraan kamu...">${esc(state.workings?.[f.id]||'')}</textarea>`;
 return `<section class="field" aria-labelledby="label-${f.id}"><div class="field-label" id="label-${f.id}"><${f.type==='text'?'label for="'+f.id+'"':'span'}>${esc(f.label)}</${f.type==='text'?'label':'span'}><span class="marks">${f.max} markah</span></div>${input}</section>`;}
function updateProgress(){const done=fields.filter(answered).length;$('#progress-label').textContent=`${done}/${fields.length} jawapan`;$('#progress-fill').style.width=`${done/fields.length*100}%`;$('#nav-groups').innerHTML=nav();bindNav();$('#saved').textContent=storageOK?'Disimpan pada peranti ini.':'Penyimpanan tidak tersedia. Kekalkan halaman ini terbuka.';}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.index=+b.dataset.nav;persist();renderExam();});}
function renderExam(){if(Date.now()-state.started>=DURATION){submit(true);return;}state.index=Math.max(0,Math.min(QUESTIONS.length-1,state.index||0));const q=QUESTIONS[state.index];$('#main').innerHTML=`<div class="exam-top"><span id="progress-label"></span><div class="progress"><span id="progress-fill"></span></div><span class="timer" id="timer" aria-label="Baki masa"></span><button id="submit-top">Hantar</button></div><div class="exam-layout"><aside class="card sidebar"><h3>Peta soalan</h3><div class="nav-groups" id="nav-groups"></div><p class="legend">Hijau muda: lengkap<br>Garis kuning: semak kemudian</p></aside><article class="card question"><div class="q-heading"><span class="pill">BAHAGIAN ${q.section} · ${q.fields.reduce((n,f)=>n+f.max,0)} MARKAH</span><button class="ghost" id="flag" aria-pressed="${state.flags.includes(q.id)}">${state.flags.includes(q.id)?'★ Ditandakan':'☆ Semak nanti'}</button></div><h2 tabindex="-1" id="question-title">${esc(q.title)}</h2><p>${esc(q.intro)}</p>${q.table?tableHTML(q.table):''}${q.image?`<figure class="math-figure"><img src="${esc(q.image)}" alt="${esc(q.imageAlt)}"><figcaption>${esc(q.imageAlt)}</figcaption></figure>`:''}${(q.section==='C'||EXAM.key==='matematik')?'<p class="muted" style="font-size:12px">Jawab dengan langkah yang jelas. Skema dan markah kaedah boleh disemak selepas tamat.</p>':''}${q.fields.map(fieldHTML).join('')}<div class="actions"><button class="secondary left" id="prev" ${state.index===0?'disabled':''}>← Sebelum</button><button id="next">${state.index===QUESTIONS.length-1?'Hantar jawapan':'Seterusnya →'}</button></div><p class="save-note" id="saved" role="status"></p></article></div>`;
 updateProgress();tick();$('#submit-top').onclick=()=>submit(false);$('#prev').onclick=()=>navigate(-1);$('#next').onclick=()=>state.index===QUESTIONS.length-1?submit(false):navigate(1);
 $('#flag').onclick=()=>{state.flags=state.flags.includes(q.id)?state.flags.filter(v=>v!==q.id):[...state.flags,q.id];persist();renderExam();};
 document.querySelectorAll('[data-math]').forEach(el=>el.addEventListener('input',()=>{state.answers[el.name]=el.value;persist();updateProgress();}));
 document.querySelectorAll('[data-work]').forEach(el=>el.addEventListener('input',()=>{state.workings=state.workings||{};state.workings[el.dataset.work]=el.value;persist();$('#saved').textContent=storageOK?'Jawapan dan jalan kerja disimpan.':'Penyimpanan tidak tersedia.';}));
 document.querySelectorAll('[data-choice]').forEach(el=>el.addEventListener('change',()=>{if(el.value==='')delete state.answers[el.name];else state.answers[el.name]=+el.value;persist();updateProgress();}));
 document.querySelectorAll('input[type=radio]').forEach(el=>el.addEventListener('change',()=>{state.answers[el.name]=+el.value;persist();updateProgress();}));document.querySelectorAll('textarea[name]').forEach(el=>el.addEventListener('input',()=>{state.answers[el.name]=el.value;persist();updateProgress();}));document.querySelectorAll('[data-table]').forEach(el=>el.addEventListener('input',()=>{const id=el.dataset.table;const v=Array.isArray(state.answers[id])?[...state.answers[id]]:Array(6).fill('');v[+el.dataset.cell]=el.value;state.answers[id]=v;persist();updateProgress();}));}
function navigate(delta){state.index+=delta;persist();renderExam();$('#question-title').focus();window.scrollTo({top:0,behavior:'smooth'});}
function tick(){if(state?.status!=='exam')return;const remaining=Math.max(0,state.started+DURATION-Date.now());const timer=$('#timer');if(timer){const sec=Math.ceil(remaining/1000);timer.textContent=`${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;timer.classList.toggle('urgent',remaining<5*60*1000);}if(remaining<=0)submit(true);}
async function submit(auto){if(state?.status!=='exam')return;if(!auto){const n=fields.filter(f=>!answered(f)).length;if(!await confirmAction('Hantar kertas jawapan?',n?`${n} ruang jawapan belum lengkap. Jawapan kosong mendapat 0 markah. Selepas dihantar, jawapan tidak boleh diubah.`:'Semua ruang sudah diisi. Selepas dihantar, jawapan tidak boleh diubah.','Hantar sekarang'))return;if(state.status!=='exam')return;}
 state.status='result';state.ended=Date.now();state.autoSubmitted=auto;state.confirmed=false;persist();$('#confirm').open&&$('#confirm').close();renderResults();window.scrollTo(0,0);}
function copyAnswer(f){const a=state.answers[f.id];if(isChoice(f))return Number.isInteger(a)?f.options[a]:'Tidak dijawab';if(f.type==='table')return Array.isArray(a)?[a.slice(0,2),a.slice(2,4),a.slice(4,6)].map(r=>r.map(v=>v||'—').join(' | ')).join('\n'):'Tidak dijawab';return a||'Tidak dijawab';}
function renderResults(){const t=total(),p=t*2;$('#main').innerHTML=`<span class="pill">${esc(EXAM.label)} · Set ${EXAM.setNumber}</span><div class="eyebrow">SELESAI · ${esc(state.name||('PELAJAR '+EXAM.label.toUpperCase()))}</div><h1 style="font-size:38px">${state.confirmed?'Keputusan disahkan.':'Masa untuk semak & belajar.'}</h1><section class="score-hero"><div><div class="status">${state.confirmed?'MARKAH SELEPAS SEMAKAN IBU BAPA':'CADANGAN MARKAH · BELUM DISAHKAN'}</div><div class="score-number">${t}<small> / 50</small></div><span class="muted">${p}% · ${state.autoSubmitted?'Dihantar automatik apabila masa tamat':'Kertas telah dihantar'}</span></div><div class="grade" aria-label="Gred ${grade(p)}">${grade(p)}</div></section><div class="result-meta ${EXAM.key==='matematik'?'two-sections':''}">${sectionIds.map((s,i)=>`<div class="card"><span class="muted">Bahagian ${s}</span><strong>${total(s)} / ${EXAM.sections[i].max}</strong><span class="muted">${EXAM.key==='matematik'?(state.confirmed?'Disemak ibu bapa':'Semakan jawapan akhir'):s==='C'?(state.confirmed?'Disemak ibu bapa':'Cadangan kata kunci'):'Semakan automatik'}</span></div>`).join('')}</div><p class="grade-note">Gred latihan: A 80–100% · B 65–79% · C 50–64% · D 40–49% · E 0–39%. Ini skala latihan laman ini, bukan pengesahan gred atau tahap penguasaan rasmi sekolah.</p>${!state.confirmed?`<div class="notice"><strong>${EXAM.key==='matematik'?'Semak jalan kerja sebelum sahkan gred.':'Semak Bahagian C sebelum sahkan gred.'}</strong> ${EXAM.key==='matematik'?'Semakan automatik membandingkan jawapan akhir. Markah kaedah bagi jawapan salah belum diambil kira. Bandingkan jalan kerja dengan skema untuk memberi markah separa.':'Sistem kata kunci boleh tersalah menilai ayat, penafian dan jawapan alternatif. Bandingkan setiap jawapan dengan skema.'} Buka mod ibu bapa untuk melaras markah.</div>`:'<div class="notice">Markah bertulis telah disahkan melalui semakan ibu bapa pada peranti ini.</div>'}<div class="actions no-print"><button class="secondary" id="export">Muat turun keputusan</button><button class="secondary" id="print">Cetak / PDF</button><button id="parent">${state.parentMode?'Tutup mod ibu bapa':'Semak sebagai ibu bapa'}</button></div>${state.parentMode?'<div class="card review-mode no-print"><strong>Mod semakan ibu bapa</strong><p>Mod ini tiada kata laluan. Semak jawapan dan jalan kerja satu demi satu dan pilih markah yang munasabah. Bukan sistem peperiksaan berpengawasan.</p><button id="confirm-grade">Sahkan semua markah & gred</button></div>':''}${EXAM.key==='matematik'?topicResults():''}<h2 style="margin-top:32px">Jawapan & skema</h2>${QUESTIONS.map(q=>`<details class="card review" ${state.parentMode&&q.fields.some(needsReview)?'open':''}><summary>Bahagian ${q.section} · ${esc(q.title)} <span class="score-tag">${q.fields.reduce((n,f)=>n+score(f),0)} / ${q.fields.reduce((n,f)=>n+f.max,0)}</span></summary><div class="review-body">${q.fields.map(f=>`<section class="review-field"><div class="field-label"><span>${esc(f.label)}</span><span class="score-tag">${score(f)} / ${f.max}</span></div><p class="muted">Jawapan kamu</p><div class="answer-copy">${esc(copyAnswer(f))}</div>${f.type==='math'?`<p class="muted">Jalan kerja kamu</p><div class="answer-copy">${esc(state.workings?.[f.id]||'Tidak ditulis')}</div>`:''}<p class="model"><strong>Skema:</strong> ${esc(f.model)}</p>${needsReview(f)?`<p class="muted" style="font-size:12px">${state.overrides?.[f.id]!==undefined?'Markah dilaras ibu bapa.':EXAM.key==='matematik'?'Cadangan berdasarkan jawapan akhir; semak jalan kerja untuk markah separa.':'Cadangan automatik; terima jawapan setara mengikut maksud jawapan.'}</p>${state.parentMode?`<label class="score-control">Markah ibu bapa<select data-score="${f.id}" aria-label="Markah ${f.id}">${Array.from({length:f.max+1},(_,i)=>`<option value="${i}" ${score(f)===i?'selected':''}>${i} / ${f.max}</option>`).join('')}</select></label>`:''}`:''}</section>`).join('')}</div></details>`).join('')}<div class="actions no-print"><button class="secondary" id="retry">Cuba sekali lagi</button></div><p class="privacy">Rekod percubaan ini disimpan pada pelayar ini sahaja. Muat turun keputusan untuk menyimpannya. Jawapan dan skema dimuatkan dalam pelayar untuk latihan kendiri.</p>`;
 $('#parent').onclick=()=>{state.parentMode=!state.parentMode;persist();renderResults();};$('#confirm-grade')?.addEventListener('click',async()=>{if(await confirmAction('Sahkan markah bertulis?','Sahkan bahawa jawapan bertulis atau jalan kerja sudah dibandingkan dengan skema dan markah telah disemak.','Sahkan gred')){state.confirmed=true;state.parentMode=false;state.reviewedAt=Date.now();persist();renderResults();toast('Markah & gred disahkan.');}});
 document.querySelectorAll('[data-score]').forEach(el=>el.onchange=()=>{const open=[...document.querySelectorAll('details')].map(d=>d.open);const y=window.scrollY;state.overrides[el.dataset.score]=+el.value;state.confirmed=false;persist();renderResults();document.querySelectorAll('details').forEach((d,i)=>d.open=open[i]);window.scrollTo(0,y);});
 $('#print').onclick=()=>{const open=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true);window.print();document.querySelectorAll('details').forEach((d,i)=>d.open=open[i]);};$('#export').onclick=exportResults;$('#retry').onclick=async()=>{if(await confirmAction('Percubaan baharu?','Rekod pada peranti ini akan diganti. Muat turun keputusan dahulu jika perlu.','Mula semula')){const name=state.name;state=null;welcome();$('#student').value=name;}};}
function exportResults(){const data={exam:'UASA '+EXAM.label+' Tahun 6 - Set latihan '+EXAM.setNumber,name:state.name,started:new Date(state.started).toISOString(),submitted:new Date(state.ended).toISOString(),confirmed:state.confirmed,score:total(),maximum:50,percentage:total()*2,grade:grade(total()*2),gradeScale:'Latihan: A>=80 B>=65 C>=50 D>=40 E<40',answers:fields.map(f=>({section:f.section,question:f.id,answer:copyAnswer(f),model:f.model,score:score(f),maximum:f.max,workings:state.workings?.[f.id]||'',topic:f.topic,marking:EXAM.key==='matematik'?'Semakan jawapan akhir / semakan kaedah ibu bapa':needsReview(f)?'Cadangan kata kunci / semakan ibu bapa':'Automatik'}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=EXAM.filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});welcome();
